(3830334, 541986, 34763, '<td valign="top">Looks like a beautiful day in Bryce Canyon</td>', 'Looks like a beautiful day in Bryce Canyon', '2007-06-25 02:38:49.000000', NULL, 1),
(3830339, 541542, 39430, '<td valign="top">Nice image.  There''s something distracting about the light on her face though.  It looks like you have a reflector in there somwhere, but it doesn''t fit the image, and makes here look like a ghost.  The face lighting might have been better brought up in post editing, to increase the contrast without ghosting her.</td>', 'Nice image.  There''s something distracting about the light on her face though.  It looks like you have a reflector in there somwhere, but it doesn''t fit the image, and makes here look like a ghost.  The face lighting might have been better brought up in post editing, to increase the contrast without ghosting her.', '2007-06-25 02:40:47.000000', NULL, 1),
(3830346, 541108, 39430, '<td valign="top">Something about that car makes me want to put "Just married" on the back, and have a couple kissing in the back window.  Maybe a really old couple, because it looks like the''ve been there a while.  :)</td>', 'Something about that car makes me want to put "Just married" on the back, and have a couple kissing in the back window.  Maybe a really old couple, because it looks like the''ve been there a while.  :)', '2007-06-25 02:42:50.000000', NULL, 1),
(3830349, 541103, 39430, '<td valign="top">Nice architecture shot.  Something is funny about the colours, like the blue is too blue, and the rest of the colours are too brown.</td>', 'Nice architecture shot.  Something is funny about the colours, like the blue is too blue, and the rest of the colours are too brown.', '2007-06-25 02:45:04.000000', NULL, 1),
(3830354, 542768, 39430, '<td valign="top">Make sure you have your white balance adjusted nicely, especially before boosting the colours.  Everything has a blue cast, and it really shows up on their eyes.</td>', 'Make sure you have your white balance adjusted nicely, especially before boosting the colours.  Everything has a blue cast, and it really shows up on their eyes.', '2007-06-25 02:46:17.000000', NULL, 1),
(3830357, 542609, 53964, '<td valign="top">Am I blind or is there really nobody in this one?</td>', 'Am I blind or is there really nobody in this one?', '2007-06-25 02:47:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3830358, 542478, 53964, '<td valign="top">The vignetting is just a touch heavy for MY taste, but lovely colour and subject.</td>', 'The vignetting is just a touch heavy for MY taste, but lovely colour and subject.', '2007-06-25 02:47:42.000000', NULL, 1),
(3830360, 542092, 53964, '<td valign="top">I give... where is he?</td>', 'I give... where is he?', '2007-06-25 02:47:49.000000', NULL, 1),
(3830361, 541794, 39430, '<td valign="top">Nice camo!  The feeling of the shot is very tropical-war.</td>', 'Nice camo!  The feeling of the shot is very tropical-war.', '2007-06-25 02:47:59.000000', NULL, 1),
(3830365, 542452, 39430, '<td valign="top">I was going to say this is too saturated and looks like a toy-town.  Well, my comment was right on the mark, or you have a giant problem.  Excuse me while I smack myself in the forehead.  :)</td>', 'I was going to say this is too saturated and looks like a toy-town.  Well, my comment was right on the mark, or you have a giant problem.  Excuse me while I smack myself in the forehead.  :)', '2007-06-25 02:49:29.000000', NULL, 1),
(3830370, 541837, 39430, '<td valign="top">With the large variation in brightness levels, this should could really do with some dual-editing.  If you shoot in raw, you can use contrast masking or HDR.  If you shoot JPG, you can''t do as much, but a little editing can still help to balance the brightness around the shot.</td>', 'With the large variation in brightness levels, this should could really do with some dual-editing.  If you shoot in raw, you can use contrast masking or HDR.  If you shoot JPG, you can''t do as much, but a little editing can still help to balance the brightness around the shot.', '2007-06-25 02:51:18.000000', NULL, 1),
(3830372, 540458, 39430, '<td valign="top">OK, yep, found them.  Interesting colouring.  Was it like this, or is this edited?</td>', 'OK, yep, found them.  Interesting colouring.  Was it like this, or is this edited?', '2007-06-25 02:52:21.000000', NULL, 1),
(3830377, 542634, 39430, '<td valign="top">Nice shot, and nice colouring in the editing.  I''d like to see a wider crop, with the subject not quite so centred.  Maybe on a thirds point instead.</td>', 'Nice shot, and nice colouring in the editing.  I''d like to see a wider crop, with the subject not quite so centred.  Maybe on a thirds point instead.', '2007-06-25 02:53:32.000000', NULL, 1),
(3830381, 542874, 76430, '<td valign="top">Someone standing on the left edge 2nd sidewalk.  Nice building, lighting, composition.</td>', 'Someone standing on the left edge 2nd sidewalk.  Nice building, lighting, composition.', '2007-06-25 02:55:40.000000', NULL, 1),
(3830383, 542261, 39430, '<td valign="top">The colours have a blue cast which is distracting.  I also wonder whether the right hand side of the image adds anything to the composition.  It might be worth trying a closer crop to see how it looks.</td>', 'The colours have a blue cast which is distracting.  I also wonder whether the right hand side of the image adds anything to the composition.  It might be worth trying a closer crop to see how it looks.', '2007-06-25 02:56:06.000000', NULL, 1),
(3830390, 541982, 39430, '<td valign="top">Nice contrast, although the overall image is a little dark to my eye.  I assume the person is standing on the log.  It might be nicer if they were standing a little more interestingly, so that when you are looking right at them, you can tell whether or not it is a person.  Then again, maybe I''m looking in the wrong place.</td>', 'Nice contrast, although the overall image is a little dark to my eye.  I assume the person is standing on the log.  It might be nicer if they were standing a little more interestingly, so that when you are looking right at them, you can tell whether or not it is a person.  Then again, maybe I''m looking in the wrong place.', '2007-06-25 02:58:31.000000', NULL, 1),
(3830406, 541273, 39430, '<td valign="top">It''s called peek-a-boo, but she''s not peeking at us at all.  The bright sunshine is washing out all the colours too.  Overcast weather or sunset can often be much better for photos like this, as the lighting is much less harsh.</td>', 'It''s called peek-a-boo, but she''s not peeking at us at all.  The bright sunshine is washing out all the colours too.  Overcast weather or sunset can often be much better for photos like this, as the lighting is much less harsh.', '2007-06-25 03:01:51.000000', NULL, 1),
(3830412, 542372, 39430, '<td valign="top">Wow, this is an incredible place.  I love the hidden horizon and the soft water</td>', 'Wow, this is an incredible place.  I love the hidden horizon and the soft water', '2007-06-25 03:03:08.000000', NULL, 1),
(3830416, 541089, 73601, '<td valign="top">nice shot, sorry for the DQ</td>', 'nice shot, sorry for the DQ', '2007-06-25 03:04:18.000000', NULL, 1),
(3830419, 542492, 39430, '<td valign="top">I''m really not fond of the editing on this shot.  And is there actually a hidden person there?</td>', 'I''m really not fond of the editing on this shot.  And is there actually a hidden person there?', '2007-06-25 03:05:14.000000', NULL, 1),
(3830420, 541994, 76430, '<td valign="top">I see the good catch of a bear peeking out from behind the tree, but I don''t see your "Hide a person in your otherwise person-less photo."  I''m suspecting DNMC, but won''t judge it assuming you hid a person unseen by the bear.</td>', 'I see the good catch of a bear peeking out from behind the tree, but I don''t see your "Hide a person in your otherwise person-less photo."  I''m suspecting DNMC, but won''t judge it assuming you hid a person unseen by the bear.', '2007-06-25 03:05:44.000000', NULL, 1),
(3830423, 542818, 39430, '<td valign="top">I know the challenge is to ''hide'' the person, but I''d actually like to see them a little more clearly, so when you find them, it''s more obviously a person, perhaps standing clear of the doorframe, and a slightly higher camera point, to get the light surrounding.  Other than that, a good idea, and a nice photo.</td>', 'I know the challenge is to ''hide'' the person, but I''d actually like to see them a little more clearly, so when you find them, it''s more obviously a person, perhaps standing clear of the doorframe, and a slightly higher camera point, to get the light surrounding.  Other than that, a good idea, and a nice photo.', '2007-06-25 03:09:44.000000', NULL, 1),
(3830426, 541023, 39430, '<td valign="top">Really nice colours a contrast, capturing a very dreamy effect.  I''d be inclined to bring out some of the dark area detail more.</td>', 'Really nice colours a contrast, capturing a very dreamy effect.  I''d be inclined to bring out some of the dark area detail more.', '2007-06-25 03:10:57.000000', NULL, 1),
(3830428, 540274, 39430, '<td valign="top">Nice shot.  Pity it''s so small from the panorama.</td>', 'Nice shot.  Pity it''s so small from the panorama.', '2007-06-25 03:11:59.000000', NULL, 1),
(3830433, 539518, 39430, '<td valign="top">Great job on matching the colours.  :)  Very funny.  The crop is a little off, but doesn''t detract too much.</td>', 'Great job on matching the colours.  :)  Very funny.  The crop is a little off, but doesn''t detract too much.', '2007-06-25 03:14:46.000000', NULL, 1),
(3830437, 541982, 76430, '<td valign="top">Sitting on the left end of the fallen tree?</td>', 'Sitting on the left end of the fallen tree?', '2007-06-25 03:17:24.000000', NULL, 1),
(3830438, 542871, 17990, '<td valign="top">I really cant find anyone... But the picture is magical! I loved it :)</td>', 'I really cant find anyone... But the picture is magical! I loved it :)', '2007-06-25 03:17:34.000000', NULL, 1),
(3830449, 541337, 39430, '<td valign="top">Harsh midday sun is often tricky.</td>', 'Harsh midday sun is often tricky.', '2007-06-25 03:24:48.000000', NULL, 1),
(3830452, 542478, 39430, '<td valign="top">The vignetting is a bit too strong for my taste</td>', 'The vignetting is a bit too strong for my taste', '2007-06-25 03:26:34.000000', NULL, 1),
(3830455, 540929, 39430, '<td valign="top">Great work on the makeup!</td>', 'Great work on the makeup!', '2007-06-25 03:27:37.000000', NULL, 1),
(3830457, 541744, 39430, '<td valign="top">Great shot.  Pity about the lamp shadows.  I like the title too.</td>', 'Great shot.  Pity about the lamp shadows.  I like the title too.', '2007-06-25 03:28:50.000000', NULL, 1),
(3830460, 542498, 39430, '<td valign="top">The dark sky is a bit too strong and unnatural.</td>', 'The dark sky is a bit too strong and unnatural.', '2007-06-25 03:29:50.000000', NULL, 1),
(3830462, 542607, 76430, '<td valign="top">camoflaged face through the corn.  Good one.  I''m wondering if he''s standing in a pit?  I was thinking of doing a camoflage picture, but didn''t have time or materials.</td>', 'camoflaged face through the corn.  Good one.  I''m wondering if he''s standing in a pit?  I was thinking of doing a camoflage picture, but didn''t have time or materials.', '2007-06-25 03:30:25.000000', NULL, 1),
(3830463, 542071, 39430, '<td valign="top">Good idea.  I''d prefer to see them facing the camera, and more even with the white posts.  But a good shot nonetheless.</td>', 'Good idea.  I''d prefer to see them facing the camera, and more even with the white posts.  But a good shot nonetheless.', '2007-06-25 03:30:55.000000', NULL, 1),
(3830464, 540993, 35669, '<td valign="top">this is dead sexy</td>', 'this is dead sexy', '2007-06-25 03:31:07.000000', NULL, 1),
(3830465, 542221, 39430, '<td valign="top">The focus is a bit off.  It would improve it to be pin-sharp.</td>', 'The focus is a bit off.  It would improve it to be pin-sharp.', '2007-06-25 03:31:55.000000', NULL, 1),
(3830472, 542816, 39430, '<td valign="top">Now that''s a good way to keep us searching this image, even if there really is nobody there.  :)</td>', 'Now that''s a good way to keep us searching this image, even if there really is nobody there.  :)', '2007-06-25 03:33:47.000000', NULL, 1),
(3830473, 540517, 39430, '<td valign="top">Very grand scenery.  It''s a pity the photo has serious colour problems.  It looks like a scanned photo from the 1970s.</td>', 'Very grand scenery.  It''s a pity the photo has serious colour problems.  It looks like a scanned photo from the 1970s.', '2007-06-25 03:35:02.000000', NULL, 1),
(3830476, 542741, 39430, '<td valign="top">I thought about this idea.  Very impressive climb.  It''s a pity the person is totally lost by their size.</td>', 'I thought about this idea.  Very impressive climb.  It''s a pity the person is totally lost by their size.', '2007-06-25 03:36:39.000000', NULL, 1),
(3830478, 542594, 39430, '<td valign="top">Nice leading lines.</td>', 'Nice leading lines.', '2007-06-25 03:37:16.000000', NULL, 1),
(3830481, 542349, 76430, '<td valign="top">In the garden left of the framework.</td>', 'In the garden left of the framework.', '2007-06-25 03:38:25.000000', NULL, 1),
(3830501, 542621, 31637, '<td valign="top">not yet, didnt see...5</td>', 'not yet, didnt see...5', '2007-06-25 03:54:58.000000', NULL, 1),
(3830503, 542374, 31637, '<td valign="top">cant find waldo 5</td>', 'cant find waldo 5', '2007-06-25 03:55:16.000000', NULL, 1),
(3830505, 542598, 68573, '<td valign="top">Great work, the sepia gives it a wonderful feel</td>', 'Great work, the sepia gives it a wonderful feel', '2007-06-25 03:55:53.000000', NULL, 1),
(3830506, 541108, 31637, '<td valign="top">grimy feel and spooky. where is waldo???? , be back for 2nd look...5</td>', 'grimy feel and spooky. where is waldo???? , be back for 2nd look...5', '2007-06-25 03:57:38.000000', NULL, 1),
(3830541, 538889, 68035, '<td valign="top">Lovely shot, and I think I found Waldo (head peering over some rocks just under half way down and slightly to the right????) But the wonderful thing is I am not sure.  Lovely image although (imo) perhaps could have done witha touch more contrast.</td>', 'Lovely shot, and I think I found Waldo (head peering over some rocks just under half way down and slightly to the right????) But the wonderful thing is I am not sure.  Lovely image although (imo) perhaps could have done witha touch more contrast.', '2007-06-25 04:19:24.000000', NULL, 1),
(3830544, 540892, 68035, '<td valign="top">Lovely shot and I think I have found Waldo  (to the left of the window???) I love the feeling of slight dereliction about this shot.  The black and white conversion may be considered by some to be harsh, but it works for me</td>', 'Lovely shot and I think I have found Waldo  (to the left of the window???) I love the feeling of slight dereliction about this shot.  The black and white conversion may be considered by some to be harsh, but it works for me', '2007-06-25 04:21:22.000000', NULL, 1),
(3830546, 542878, 68035, '<td valign="top">There''s a giant outside!!!!!!  Lovely weird image (I can never pull off taking shots of toys) very surreal</td>', 'There''s a giant outside!!!!!!  Lovely weird image (I can never pull off taking shots of toys) very surreal', '2007-06-25 04:22:35.000000', NULL, 1),
(3830548, 542880, 68035, '<td valign="top">Well the red top kinda gives it away.  Interesting shot</td>', 'Well the red top kinda gives it away.  Interesting shot', '2007-06-25 04:23:42.000000', NULL, 1),
(3830551, 542031, 68035, '<td valign="top">OK well you got me beat cos I cant find him.  Beautiful composition in this photo I love the way you have framed the tree, you get a real sense of its size.  The B&amp;W conversion is good but slightly noisy on my monitor</td>', 'OK well you got me beat cos I cant find him.  Beautiful composition in this photo I love the way you have framed the tree, you get a real sense of its size.  The B&W conversion is good but slightly noisy on my monitor', '2007-06-25 04:26:27.000000', NULL, 1),
(3830554, 542745, 68035, '<td valign="top">OK well I found Waldo by the fountain (Is there another just by the second floot hut as well?) .  Very nice shot and the centring works well.  the sky colouration is fantastic is this through a polarising filter or PP work, either way it gives a remarkable feel to the picture</td>', 'OK well I found Waldo by the fountain (Is there another just by the second floot hut as well?) .  Very nice shot and the centring works well.  the sky colouration is fantastic is this through a polarising filter or PP work, either way it gives a remarkable feel to the picture', '2007-06-25 04:28:50.000000', NULL, 1),
(3830556, 541033, 31637, '<td valign="top">Wow, would of been great for the Sci Fi challenge too!</td>', 'Wow, would of been great for the Sci Fi challenge too!', '2007-06-25 04:29:28.000000', NULL, 1),
(3830557, 540746, 68035, '<td valign="top">LOL good job, I did eventually find Waldo (which I should have done more easily considering the red top!).  Very nice composition here especially in terms of rule of thirds.  Good job</td>', 'LOL good job, I did eventually find Waldo (which I should have done more easily considering the red top!).  Very nice composition here especially in terms of rule of thirds.  Good job', '2007-06-25 04:30:36.000000', NULL, 1),
(3830559, 542828, 31637, '<td valign="top">Great shot, the face is exposed enough! 9</td>', 'Great shot, the face is exposed enough! 9', '2007-06-25 04:30:41.000000', NULL, 1),
(3830562, 542816, 68035, '<td valign="top">Fantastic!!! I spotted the jeans quite quickly but actually thought that the bra and pants where flowers on a bush for a while.  Cant actually see a Waldo but this is a lovely shot and very well composed.  Good and amusing take on the challenge</td>', 'Fantastic!!! I spotted the jeans quite quickly but actually thought that the bra and pants where flowers on a bush for a while.  Cant actually see a Waldo but this is a lovely shot and very well composed.  Good and amusing take on the challenge', '2007-06-25 04:32:41.000000', NULL, 1),
(3830570, 541117, 68035, '<td valign="top">Is that Waldo in the roof of the potting shed?  Very bizarre!!!.  Super simple crisp shot nicely executed great focus</td>', 'Is that Waldo in the roof of the potting shed?  Very bizarre!!!.  Super simple crisp shot nicely executed great focus', '2007-06-25 04:34:04.000000', NULL, 1),
(3830581, 542776, 68035, '<td valign="top">OK so your Waldos were not too hard to find, but so what.  This is a good shot and your capture of the cascading water is fantastic.  Unfortunately at the top of the falls there is a red line running to the right of the water which is very off putting.  Really think that it might have been worth cropping down bewlow that to remove it (appreciating that this would have made you Waldos bigger)</td>', 'OK so your Waldos were not too hard to find, but so what.  This is a good shot and your capture of the cascading water is fantastic.  Unfortunately at the top of the falls there is a red line running to the right of the water which is very off putting.  Really think that it might have been worth cropping down bewlow that to remove it (appreciating that this would have made you Waldos bigger)', '2007-06-25 04:36:39.000000', NULL, 1),
(3830583, 542862, 68035, '<td valign="top">OK I have to say I got your Waldo fairly quickly but to be honest who cares.  I like this image a lot.  Plenty going on but because you have got such crisp lines it doesnt feel cluttered or overbearing.  Really tight B&amp;W conversion as well.  Lovely contrasts</td>', 'OK I have to say I got your Waldo fairly quickly but to be honest who cares.  I like this image a lot.  Plenty going on but because you have got such crisp lines it doesnt feel cluttered or overbearing.  Really tight B&W conversion as well.  Lovely contrasts', '2007-06-25 04:38:30.000000', NULL, 1),
(3830585, 542611, 68035, '<td valign="top">OK I will be honest and say I got your Waldo fairly quickly although I really like the way that compositionally he is unintentionally mimicing the lamp posts which I think creates a very pleasing effect.  Quite like the dof (though possibly could have been a shade deeper for my own tastes) and a good B&amp;W conversion</td>', 'OK I will be honest and say I got your Waldo fairly quickly although I really like the way that compositionally he is unintentionally mimicing the lamp posts which I think creates a very pleasing effect.  Quite like the dof (though possibly could have been a shade deeper for my own tastes) and a good B&W conversion', '2007-06-25 04:40:40.000000', NULL, 1),
(3830586, 540275, 68035, '<td valign="top">OK I got your Waldo quite quickly but that matters not one jot.  Fantastic perpsective and the diagonal works so well.  Super repetive patterns (not just of the roof but also of the floor signs lights etc and a nice B&amp;W conversion.  This grows on me more and more</td>', 'OK I got your Waldo quite quickly but that matters not one jot.  Fantastic perpsective and the diagonal works so well.  Super repetive patterns (not just of the roof but also of the floor signs lights etc and a nice B&W conversion.  This grows on me more and more', '2007-06-25 04:42:41.000000', NULL, 1),
(3830589, 540517, 68035, '<td valign="top">OK I spotted our Waldo on the path.  Nice shot of a breathtaking view.  IMO the colours seem a little flat but still a nice shot</td>', 'OK I spotted our Waldo on the path.  Nice shot of a breathtaking view.  IMO the colours seem a little flat but still a nice shot', '2007-06-25 04:43:55.000000', NULL, 1),
(3830592, 542383, 68035, '<td valign="top">LOL well I found your Waldo but that matters not a jot.  Absolutely wonderful image of the bridge with unbelieveable focus.  The skyli is magnificent and the great thing is that this shot meets the challenge 100% but does not feel in the least contrived.  Your Waldo blends in yet enhances the overall picture - 9</td>', 'LOL well I found your Waldo but that matters not a jot.  Absolutely wonderful image of the bridge with unbelieveable focus.  The skyli is magnificent and the great thing is that this shot meets the challenge 100% but does not feel in the least contrived.  Your Waldo blends in yet enhances the overall picture - 9', '2007-06-25 04:45:52.000000', NULL, 1),
(3830595, 541108, 68035, '<td valign="top">LOL is that Waldo in the car?  What a fantastic image beautiful sense of desertion and solitude.  The duotone works fantastically and you have an image which doesnt simply meet the challenge but which is beautiful and haunting to look at</td>', 'LOL is that Waldo in the car?  What a fantastic image beautiful sense of desertion and solitude.  The duotone works fantastically and you have an image which doesnt simply meet the challenge but which is beautiful and haunting to look at', '2007-06-25 04:47:45.000000', NULL, 1),
(3830597, 542500, 68035, '<td valign="top">LOL...Waldo''s a tree hugger!!!!  Wonderful shot and the diagonal composition works well.  Find mysef stunned that these trees have grown so uniformedly.  Excellent capture.  One small minus is that the white of the sunlight seems a touch blown out on my monitor</td>', 'LOL...Waldo''s a tree hugger!!!!  Wonderful shot and the diagonal composition works well.  Find mysef stunned that these trees have grown so uniformedly.  Excellent capture.  One small minus is that the white of the sunlight seems a touch blown out on my monitor', '2007-06-25 04:49:39.000000', NULL, 1),
(3830603, 540553, 68035, '<td valign="top">Oooo sneaky!!!  That took a little while.  Great shot and magical composition.  Great silhouetting of Atlas which really helps emphasise the detail of the church/cathedral.  Sky is awesome!!!!! 8</td>', 'Oooo sneaky!!!  That took a little while.  Great shot and magical composition.  Great silhouetting of Atlas which really helps emphasise the detail of the church/cathedral.  Sky is awesome!!!!! 8', '2007-06-25 04:51:44.000000', NULL, 1),
(3830605, 542813, 68035, '<td valign="top">I can see why.  Think I have spotted the white topped Waldo in the distance but dont really care as its a grey rainy day in the UK and this shot can almost make me feel the warmth of the sun on my face.  Wonderful colours</td>', 'I can see why.  Think I have spotted the white topped Waldo in the distance but dont really care as its a grey rainy day in the UK and this shot can almost make me feel the warmth of the sun on my face.  Wonderful colours', '2007-06-25 04:53:20.000000', NULL, 1),
(3830610, 542456, 68035, '<td valign="top">Wow took a little while but I have spotted one Waldo (in the guard hut) and possibly even a second (by the pillars).  Super shot I love the composition here which makes it very appealing to the eye</td>', 'Wow took a little while but I have spotted one Waldo (in the guard hut) and possibly even a second (by the pillars).  Super shot I love the composition here which makes it very appealing to the eye', '2007-06-25 04:55:31.000000', NULL, 1),
(3830613, 542230, 49109, '<td valign="top">nice image! Waldo''s very hard to find here, though</td>', 'nice image! Waldo''s very hard to find here, though', '2007-06-25 04:57:22.000000', NULL, 1),
(3830615, 542764, 68035, '<td valign="top">OK well I spotted Skipo/Waldo but who cares, this is a nice shot, really like the colour capture and the fact that even in the sunlight there is no blow out of this.  Possibly could have been cropped a shade to the right to bring the tree into exact rule of third but a good image as it is</td>', 'OK well I spotted Skipo/Waldo but who cares, this is a nice shot, really like the colour capture and the fact that even in the sunlight there is no blow out of this.  Possibly could have been cropped a shade to the right to bring the tree into exact rule of third but a good image as it is', '2007-06-25 04:57:58.000000', NULL, 1),
(3830626, 542875, 49109, '<td valign="top">very good shot, nice composition and tones. frame distracts a bit, had preferred white or none. good placing of Waldo.</td>', 'very good shot, nice composition and tones. frame distracts a bit, had preferred white or none. good placing of Waldo.', '2007-06-25 05:18:49.000000', NULL, 1),
(3830629, 542858, 49109, '<td valign="top">sky color is a bit off, too pinkish. well composed, good placing of Waldo</td>', 'sky color is a bit off, too pinkish. well composed, good placing of Waldo', '2007-06-25 05:20:04.000000', NULL, 1),
(3830632, 542478, 49109, '<td valign="top">that was too easy... nice shot, but the strong and  irregular vignetting takes away much</td>', 'that was too easy... nice shot, but the strong and  irregular vignetting takes away much', '2007-06-25 05:21:05.000000', NULL, 1),
