(3834717, 542608, 55199, '<td valign="top">Oil?  Water?  I like the realness of this shot.  I see the pipes which are impressive, then I discover the maintenance person who looks like he belongs there, and I am again impressed by the size of the pipes.  Nice job.</td>', 'Oil?  Water?  I like the realness of this shot.  I see the pipes which are impressive, then I discover the maintenance person who looks like he belongs there, and I am again impressed by the size of the pipes.  Nice job.', '2007-06-26 01:13:13.000000', NULL, 1),
(3834727, 542492, 55199, '<td valign="top">woah... freaky..  and trippy.</td>', 'woah... freaky..  and trippy.', '2007-06-26 01:17:51.000000', NULL, 1),
