(3836554, 542865, 32133, '<td valign="top">Very cool</td>', 'Very cool', '2007-06-26 14:13:02.000000', NULL, 1),
(3836559, 542828, 32133, '<td valign="top">This is so beautiful.  I love the bw effect, the camera angle, your "Waldo", the lighting effects, the scene, the bird... 10</td>', 'This is so beautiful.  I love the bw effect, the camera angle, your "Waldo", the lighting effects, the scene, the bird... 10', '2007-06-26 14:14:17.000000', NULL, 1),
