(3836564, 542873, 79167, '<td valign="top">very creative!</td>', 'very creative!', '2007-06-26 14:19:01.000000', NULL, 1),
(3836571, 542858, 79167, '<td valign="top">took me a minute...very nice, i like this one! would''ve been cool to have the same shot with the sky looking gray and cloudy like a thunderstorm was coming :)</td>', 'took me a minute...very nice, i like this one! would''ve been cool to have the same shot with the sky looking gray and cloudy like a thunderstorm was coming :)', '2007-06-26 14:21:55.000000', NULL, 1),
