(3836961, 542776, 811, '<td valign="top">The composition seems a bit right heavy to me.  Since the people are over there, and the falls "go" that way, it seems like it might be better to crop some off of the left and have more in the right side of the frame</td>', 'The composition seems a bit right heavy to me.  Since the people are over there, and the falls "go" that way, it seems like it might be better to crop some off of the left and have more in the right side of the frame', '2007-06-26 15:56:47.000000', NULL, 1),
(3836963, 542105, 811, '<td valign="top">Great colors and I like the effect of the shadows on this.</td>', 'Great colors and I like the effect of the shadows on this.', '2007-06-26 15:57:07.000000', NULL, 1),
(3836987, 542608, 811, '<td valign="top">Good composition, though the greens seem a bit saturated and bright compared to the rest of the shot.</td>', 'Good composition, though the greens seem a bit saturated and bright compared to the rest of the shot.', '2007-06-26 16:01:47.000000', NULL, 1),
