(3837038, 542628, 811, '<td valign="top">This shot is a bit "bland" in composition and color.  There isn''t a lot to compel the viewer to stay with the picture.  Maybe if it were a bit brighter and in bw it might have more redeeming features.</td>', 'This shot is a bit "bland" in composition and color.  There isn''t a lot to compel the viewer to stay with the picture.  Maybe if it were a bit brighter and in bw it might have more redeeming features.', '2007-06-26 16:09:11.000000', NULL, 1),
(3837042, 542870, 811, '<td valign="top">Very subtle.  It seems a bit contrasty which gives it a grainy look, but I think it might work for the "mood" of this shot.</td>', 'Very subtle.  It seems a bit contrasty which gives it a grainy look, but I think it might work for the "mood" of this shot.', '2007-06-26 16:09:45.000000', NULL, 1),
(3837045, 541397, 811, '<td valign="top">I''m wishing I were there too -- awesome colors and nice framing of the sun..  Seems a bit tilted to the right here.  Makes me feel like I''m leaning right.</td>', 'I''m wishing I were there too -- awesome colors and nice framing of the sun..  Seems a bit tilted to the right here.  Makes me feel like I''m leaning right.', '2007-06-26 16:10:26.000000', NULL, 1),
(3837047, 542721, 811, '<td valign="top">Great idea.  Well done.</td>', 'Great idea.  Well done.', '2007-06-26 16:10:39.000000', NULL, 1),
(3837050, 541891, 811, '<td valign="top">The trees being centered make this shot more static than dynamic.  Maybe if they were further left or right in the frame.</td>', 'The trees being centered make this shot more static than dynamic.  Maybe if they were further left or right in the frame.', '2007-06-26 16:11:25.000000', NULL, 1),
(3837051, 541405, 811, '<td valign="top">Nice lighting and reflection.</td>', 'Nice lighting and reflection.', '2007-06-26 16:11:38.000000', NULL, 1),
(3837056, 540275, 811, '<td valign="top">I like the angle you have chosen to use for this.  Also, I think bw works well to give it a "complex/simple" look.</td>', 'I like the angle you have chosen to use for this.  Also, I think bw works well to give it a "complex/simple" look.', '2007-06-26 16:12:22.000000', NULL, 1),
(3837059, 541784, 811, '<td valign="top">I like the "parallel" between the two.  The sepia tone works well, here, I think.</td>', 'I like the "parallel" between the two.  The sepia tone works well, here, I think.', '2007-06-26 16:12:53.000000', NULL, 1),
(3837061, 540833, 811, '<td valign="top">The greens are way too bright, I think, and detract from the overal effective of the shot because they distract away from the mill.</td>', 'The greens are way too bright, I think, and detract from the overal effective of the shot because they distract away from the mill.', '2007-06-26 16:13:24.000000', NULL, 1),
(3837062, 542230, 42013, '<td valign="top">Wow, this was a popular place. DC GTG? I like this one as well. Yours does great justice to the curvature of the seats.</td>', 'Wow, this was a popular place. DC GTG? I like this one as well. Yours does great justice to the curvature of the seats.', '2007-06-26 16:13:26.000000', NULL, 1),
(3837065, 542865, 811, '<td valign="top">I like this.  Had you painted her face and arm with black and white stripes, I bet it would have won.</td>', 'I like this.  Had you painted her face and arm with black and white stripes, I bet it would have won.', '2007-06-26 16:13:59.000000', NULL, 1),
(3837067, 541744, 811, '<td valign="top">Ooo, just about missed the little guy.  Good work at getting him to blend in.</td>', 'Ooo, just about missed the little guy.  Good work at getting him to blend in.', '2007-06-26 16:14:23.000000', NULL, 1),
(3837070, 541460, 811, '<td valign="top">The building looks massive beside him -- gives a very imposing look and feeling to the shot</td>', 'The building looks massive beside him -- gives a very imposing look and feeling to the shot', '2007-06-26 16:14:55.000000', NULL, 1),
(3837071, 542768, 42013, '<td valign="top">Very vivid colors.</td>', 'Very vivid colors.', '2007-06-26 16:15:05.000000', NULL, 1),
