(3838375, 541891, 53316, '<td valign="top">I love the color gradient!</td>', 'I love the color gradient!', '2007-06-26 21:37:23.000000', NULL, 1),
(3838379, 542609, 45475, '<td valign="top">Oh, this one has me stumped. I''m seeing faces everywhere in the bushes! :D Great stuff.</td>', 'Oh, this one has me stumped. I''m seeing faces everywhere in the bushes! :D Great stuff.', '2007-06-26 21:37:59.000000', NULL, 1),
(3838380, 542598, 53316, '<td valign="top">Reminds me of my dad''s garage :-)</td>', 'Reminds me of my dad''s garage :-)', '2007-06-26 21:38:09.000000', NULL, 1),
(3838383, 541103, 45475, '<td valign="top">Cool shot! What a place huh? Great colour and light, nice work :)</td>', 'Cool shot! What a place huh? Great colour and light, nice work :)', '2007-06-26 21:39:07.000000', NULL, 1),
(3838388, 540517, 45475, '<td valign="top">Finally spotted him! On the track there, yay! This is so well done. Congrats on a tricky shot :)</td>', 'Finally spotted him! On the track there, yay! This is so well done. Congrats on a tricky shot :)', '2007-06-26 21:41:51.000000', NULL, 1),
