(3838964, 542871, 45475, '<td valign="top">What an absolutely fantastic place to take photographs. Excellent entry, almost didn''t see him!</td>', 'What an absolutely fantastic place to take photographs. Excellent entry, almost didn''t see him!', '2007-06-26 23:43:28.000000', NULL, 1),
(3839060, 541405, 78255, '<td valign="top">Beautiful image of this beautiful place. Balboa Park''s botanical garden is beautiful. I have hunted for quite a while and still cannot see a person here. I tried though. :)</td>', 'Beautiful image of this beautiful place. Balboa Park''s botanical garden is beautiful. I have hunted for quite a while and still cannot see a person here. I tried though. :)', '2007-06-26 23:55:09.000000', NULL, 1),
(3839081, 542768, 78255, '<td valign="top">Love this one!</td>', 'Love this one!', '2007-06-26 23:57:42.000000', NULL, 1),
(3839098, 542106, 78255, '<td valign="top">This is a very well done Where''s Waldo image. Nice work! My 7 year old son and I had fun finding your man between the bars.</td>', 'This is a very well done Where''s Waldo image. Nice work! My 7 year old son and I had fun finding your man between the bars.', '2007-06-27 00:00:00.000000', NULL, 1),
(3839111, 542602, 78255, '<td valign="top">Made me laugh! :)</td>', 'Made me laugh! :)', '2007-06-27 00:01:19.000000', NULL, 1),
(3839138, 542634, 78255, '<td valign="top">The mans face is tinted green too. I wish it was a more pleasing green. Interesting image though.</td>', 'The mans face is tinted green too. I wish it was a more pleasing green. Interesting image though.', '2007-06-27 00:04:05.000000', NULL, 1),
(3839144, 540468, 68947, '<td valign="top">I like the "blatantness" of this shot....especially after having a headache, trying to find Waldo in some of the others!  I was getting a headache, so this is refreshing to see.</td>', 'I like the "blatantness" of this shot....especially after having a headache, trying to find Waldo in some of the others!  I was getting a headache, so this is refreshing to see.', '2007-06-27 00:04:58.000000', NULL, 1),
