(3842909, 541736, 68035, '<td valign="top">I am tearing my flaming hair out here, trying to find Waldo!!!  I dont know why but I feel certain that he is there somewhere (rather than you playing a cruel trick on the voters) and that when you point him out I will scream at my lack of observational skills<br/> <br/>Got to say that this is one of the most striking images in terms of this challenge and has been fantastically captured, I just hope for your sake that other people are better spotters than me and that you dont get marked down by anyone who cant find waldo.  This gets 9 from me<br/> <br/>Top image</td>', 'I am tearing my flaming hair out here, trying to find Waldo!!!  I dont know why but I feel certain that he is there somewhere (rather than you playing a cruel trick on the voters) and that when you point him out I will scream at my lack of observational skills Got to say that this is one of the most striking images in terms of this challenge and has been fantastically captured, I just hope for your sake that other people are better spotters than me and that you dont get marked down by anyone who cant find waldo.  This gets 9 from me Top image', '2007-06-27 19:05:49.000000', NULL, 1),
(3842913, 538547, 23146, '<td valign="top">A bit out of focus.</td>', 'A bit out of focus.', '2007-06-27 19:07:35.000000', NULL, 1),
(3843000, 542459, 45475, '<td valign="top">Great work, very dramatic.</td>', 'Great work, very dramatic.', '2007-06-27 19:40:30.000000', NULL, 1),
(3843004, 542743, 45475, '<td valign="top">Awesome spooky feel. Love the processing here.</td>', 'Awesome spooky feel. Love the processing here.', '2007-06-27 19:41:04.000000', NULL, 1),
(3843013, 540929, 45475, '<td valign="top">Gosh, what an elaborate effort. A pure delight to view and hoping this will make it to the front page. Congrats in advance!</td>', 'Gosh, what an elaborate effort. A pure delight to view and hoping this will make it to the front page. Congrats in advance!', '2007-06-27 19:43:05.000000', NULL, 1),
(3843019, 541023, 45475, '<td valign="top">Excellent dreamy quality to this. Great work.</td>', 'Excellent dreamy quality to this. Great work.', '2007-06-27 19:43:48.000000', NULL, 1),
(3843026, 542365, 45475, '<td valign="top">Must be an awesome view from there. Wow, magnificent setting. Well taken.</td>', 'Must be an awesome view from there. Wow, magnificent setting. Well taken.', '2007-06-27 19:45:19.000000', NULL, 1),
(3843042, 540567, 45475, '<td valign="top">Great use of vignetting here! No complaints about anything, excellent work :)</td>', 'Great use of vignetting here! No complaints about anything, excellent work :)', '2007-06-27 19:47:18.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3843053, 542057, 45475, '<td valign="top">How do you make an image appear hard and soft at the same time? Wonderful and atmospheric. Good idea, well executed.</td>', 'How do you make an image appear hard and soft at the same time? Wonderful and atmospheric. Good idea, well executed.', '2007-06-27 19:48:54.000000', NULL, 1),
(3843067, 542852, 45475, '<td valign="top">I like this a lot. The tree tops need a bit of something more. Not sure what though... maybe more contrast? Good work nonetheless.</td>', 'I like this a lot. The tree tops need a bit of something more. Not sure what though... maybe more contrast? Good work nonetheless.', '2007-06-27 19:50:21.000000', NULL, 1),
(3843076, 542608, 45475, '<td valign="top">Fantastic leading lines. Great colour and subject. You have a good eye.</td>', 'Fantastic leading lines. Great colour and subject. You have a good eye.', '2007-06-27 19:51:50.000000', NULL, 1),
(3843085, 540892, 45475, '<td valign="top">Interesting harsh contrast. Lots to see here. Almost didn''t spot Waldo! Well done.</td>', 'Interesting harsh contrast. Lots to see here. Almost didn''t spot Waldo! Well done.', '2007-06-27 19:54:35.000000', NULL, 1),
(3843088, 542874, 45475, '<td valign="top">Colour and light is WOW. Nice work :)</td>', 'Colour and light is WOW. Nice work :)', '2007-06-27 19:55:17.000000', NULL, 1),
(3843091, 541542, 45475, '<td valign="top">Cool. A little bit too much grey, but I like it. Nice work.</td>', 'Cool. A little bit too much grey, but I like it. Nice work.', '2007-06-27 19:56:01.000000', NULL, 1),
(3843094, 541108, 45475, '<td valign="top">It always strikes me as a little sad when I see an abandoned classic. Slightly over sharpened, but otherwise a great entry.</td>', 'It always strikes me as a little sad when I see an abandoned classic. Slightly over sharpened, but otherwise a great entry.', '2007-06-27 19:57:53.000000', NULL, 1),
(3843096, 542875, 42013, '<td valign="top">I think I see him!</td>', 'I think I see him!', '2007-06-27 19:58:25.000000', NULL, 1),
(3843099, 541397, 45475, '<td valign="top">Oh, now this is paradise. Superbly taken, just a pity you didn''t straighten the horizon. 7</td>', 'Oh, now this is paradise. Superbly taken, just a pity you didn''t straighten the horizon. 7', '2007-06-27 19:59:38.000000', NULL, 1),
(3843101, 540915, 42013, '<td valign="top">The tilt is a little distracting but I like the different take on Waldo''s placement.</td>', 'The tilt is a little distracting but I like the different take on Waldo''s placement.', '2007-06-27 20:00:31.000000', NULL, 1),
(3843102, 542106, 74496, '<td valign="top">center right</td>', 'center right', '2007-06-27 20:00:41.000000', NULL, 1),
(3843104, 542232, 74496, '<td valign="top">lower left</td>', 'lower left', '2007-06-27 20:01:16.000000', NULL, 1),
(3843106, 542855, 45475, '<td valign="top">Intriguing. I''ve taken stupid pills by accident today, so I''m not sure of the message here, but I do like the work.</td>', 'Intriguing. I''ve taken stupid pills by accident today, so I''m not sure of the message here, but I do like the work.', '2007-06-27 20:01:49.000000', NULL, 1),
(3843111, 540468, 74496, '<td valign="top">It might have been more interesting if it were not so centered</td>', 'It might have been more interesting if it were not so centered', '2007-06-27 20:02:42.000000', NULL, 1),
(3843115, 540915, 45475, '<td valign="top">Excellent take on the challenge, a great night shot. Not sure of the square crop though, feels a bit too much.</td>', 'Excellent take on the challenge, a great night shot. Not sure of the square crop though, feels a bit too much.', '2007-06-27 20:04:00.000000', NULL, 1),
(3843119, 540517, 74496, '<td valign="top">center!</td>', 'center!', '2007-06-27 20:06:19.000000', NULL, 1),
(3843126, 542477, 45475, '<td valign="top">Nice stuff. Love the idea and it''s well executed. Probably could have gotten away with cropping more off the top though. All the same, bumping to 8.</td>', 'Nice stuff. Love the idea and it''s well executed. Probably could have gotten away with cropping more off the top though. All the same, bumping to 8.', '2007-06-27 20:08:11.000000', NULL, 1),
(3843133, 541548, 74496, '<td valign="top">in front of the car,right</td>', 'in front of the car,right', '2007-06-27 20:09:33.000000', NULL, 1),
(3843139, 541460, 45475, '<td valign="top">Hehe, cute title :) The angle doesn''t really appeal to me though, the sky pokes in distractingly. Perhaps had you taken this straight on? 6</td>', 'Hehe, cute title :) The angle doesn''t really appeal to me though, the sky pokes in distractingly. Perhaps had you taken this straight on? 6', '2007-06-27 20:11:00.000000', NULL, 1),
(3843141, 538547, 74496, '<td valign="top">focus seems off</td>', 'focus seems off', '2007-06-27 20:11:14.000000', NULL, 1),
(3843144, 542626, 74496, '<td valign="top">center right</td>', 'center right', '2007-06-27 20:11:32.000000', NULL, 1),
(3843147, 542459, 74496, '<td valign="top">in the door way</td>', 'in the door way', '2007-06-27 20:12:03.000000', NULL, 1),
(3843152, 542498, 45475, '<td valign="top">A good, crisp image. Well taken, but just lacks something else... 6.</td>', 'A good, crisp image. Well taken, but just lacks something else... 6.', '2007-06-27 20:12:38.000000', NULL, 1),
(3843157, 540833, 45475, '<td valign="top">Love the saturated greens. Nice work!</td>', 'Love the saturated greens. Nice work!', '2007-06-27 20:13:28.000000', NULL, 1),
(3843163, 542221, 45475, '<td valign="top">Better focus and more contrast is what''s need here I think. Fantastic idea though! 6</td>', 'Better focus and more contrast is what''s need here I think. Fantastic idea though! 6', '2007-06-27 20:14:28.000000', NULL, 1),
(3843164, 542741, 74496, '<td valign="top">To bad (or good) for the red shirt, might have been reallly hard to spot without it!  Would have worked really well for negative space too!  Great colors</td>', 'To bad (or good) for the red shirt, might have been reallly hard to spot without it!  Would have worked really well for negative space too!  Great colors', '2007-06-27 20:14:31.000000', NULL, 1),
(3843172, 541548, 45475, '<td valign="top">Yup, I see you! Just that the scene is a little boring. Nice effort though, 6.</td>', 'Yup, I see you! Just that the scene is a little boring. Nice effort though, 6.', '2007-06-27 20:15:49.000000', NULL, 1),
(3843202, 542492, 45475, '<td valign="top">Not quite sure where you''re going with this. Looking forward to reading your notes behind the processing here after the challenge. I don''t like it, but I am intrigued. Ok, can''t see Waldo, though no doubt he''s hiding somewhere in the bushes, so you get the benefit of a 4.</td>', 'Not quite sure where you''re going with this. Looking forward to reading your notes behind the processing here after the challenge. I don''t like it, but I am intrigued. Ok, can''t see Waldo, though no doubt he''s hiding somewhere in the bushes, so you get the benefit of a 4.', '2007-06-27 20:22:16.000000', NULL, 1),
(3843210, 541337, 45475, '<td valign="top">Good colour, strong image. Nice work :)</td>', 'Good colour, strong image. Nice work :)', '2007-06-27 20:24:04.000000', NULL, 1),
(3843217, 542428, 45475, '<td valign="top">Very glad I kept coming back to this one. I spotted him now! Woohoo, I was getting so frustrated :D</td>', 'Very glad I kept coming back to this one. I spotted him now! Woohoo, I was getting so frustrated :D', '2007-06-27 20:29:21.000000', NULL, 1),
(3843220, 541273, 45475, '<td valign="top">Clean and crisp image. I think it''s blown a little judging by the sky and pink paint though.</td>', 'Clean and crisp image. I think it''s blown a little judging by the sky and pink paint though.', '2007-06-27 20:31:20.000000', NULL, 1),
(3843226, 542858, 45475, '<td valign="top">Oooh, I like how Waldo''s hidden here. Exposure feels a bit flat and probably could have benefited with a tad more sharpening. Well seen though!</td>', 'Oooh, I like how Waldo''s hidden here. Exposure feels a bit flat and probably could have benefited with a tad more sharpening. Well seen though!', '2007-06-27 20:33:01.000000', NULL, 1),
(3843227, 541722, 45475, '<td valign="top">Crossing the road? Great night shot, well done.</td>', 'Crossing the road? Great night shot, well done.', '2007-06-27 20:33:48.000000', NULL, 1),
(3843228, 542768, 45475, '<td valign="top">Very cute!</td>', 'Very cute!', '2007-06-27 20:34:09.000000', NULL, 1),
(3843232, 542387, 45475, '<td valign="top">Too heavy on the sharpening I think. The sky could use some colour too. Over exposed maybe? Nice effort though!</td>', 'Too heavy on the sharpening I think. The sky could use some colour too. Over exposed maybe? Nice effort though!', '2007-06-27 20:35:46.000000', NULL, 1),
(3843280, 538679, 45475, '<td valign="top">For a seascape, the colours are a bit dull and flat. Also, with no symmetry between the top and bottom halves of the image, the horizon should really be moved off center (and straightened) I think. Exaggerate the perspective next time by getting lower to the ground and either pointing the lens slightly toward the ground, or toward the sky.</td>', 'For a seascape, the colours are a bit dull and flat. Also, with no symmetry between the top and bottom halves of the image, the horizon should really be moved off center (and straightened) I think. Exaggerate the perspective next time by getting lower to the ground and either pointing the lens slightly toward the ground, or toward the sky.', '2007-06-27 20:52:38.000000', NULL, 1),
(3843303, 542875, 76430, '<td valign="top">Just right of dead center.  Nice sepia picture.  Good background and sky, but the road is a bit monotonous and takes up too much of the shot.  It probably would have been good for "vanishing point" though.</td>', 'Just right of dead center.  Nice sepia picture.  Good background and sky, but the road is a bit monotonous and takes up too much of the shot.  It probably would have been good for "vanishing point" though.', '2007-06-27 20:59:50.000000', NULL, 1),
(3843312, 542111, 76430, '<td valign="top">Good use of color "camoflage" to hide your "Waldo".  Nice wide-angle forest scene.</td>', 'Good use of color "camoflage" to hide your "Waldo".  Nice wide-angle forest scene.', '2007-06-27 21:01:29.000000', NULL, 1),
(3843314, 539399, 76430, '<td valign="top">Someone walking away with a green backpack on the path on the lower left thirds.  It''s not that easy to see, but it does stand out from the rest of the picture, and after a little observation becomes clear.  Nice scene.</td>', 'Someone walking away with a green backpack on the path on the lower left thirds.  It''s not that easy to see, but it does stand out from the rest of the picture, and after a little observation becomes clear.  Nice scene.', '2007-06-27 21:01:43.000000', NULL, 1),
(3843315, 540275, 76430, '<td valign="top">Waldo is clearly walking on the middle left side.  Excellent composition with the arches, angle, lighting.</td>', 'Waldo is clearly walking on the middle left side.  Excellent composition with the arches, angle, lighting.', '2007-06-27 21:01:52.000000', NULL, 1),
(3843330, 542492, 76430, '<td valign="top">With the heavy processing I would expect to be able to pick out Waldo, but for the life of me I can''t.  Interestingly processed picture.  Parts of the horse were cut off, such as hooves.  It looks like you selectively processed the background.  Not my style, but interesting.</td>', 'With the heavy processing I would expect to be able to pick out Waldo, but for the life of me I can''t.  Interestingly processed picture.  Parts of the horse were cut off, such as hooves.  It looks like you selectively processed the background.  Not my style, but interesting.', '2007-06-27 21:06:27.000000', NULL, 1),
(3843336, 542787, 76430, '<td valign="top">Walking left past the hanging stuff.  Bold division of left and right sides.</td>', 'Walking left past the hanging stuff.  Bold division of left and right sides.', '2007-06-27 21:07:10.000000', NULL, 1),
(3843338, 542628, 45475, '<td valign="top">Not sure I like what''s happened to the leaves in this, no texture. It''s a nice enough composition but a little on the boring side. Overcast daylight could be the culprit?</td>', 'Not sure I like what''s happened to the leaves in this, no texture. It''s a nice enough composition but a little on the boring side. Overcast daylight could be the culprit?', '2007-06-27 21:08:03.000000', NULL, 1),
(3843340, 542621, 76430, '<td valign="top">Sitting on the left edge of the road partially blocked by leaves?  Other than that I see no sign of Waldo.</td>', 'Sitting on the left edge of the road partially blocked by leaves?  Other than that I see no sign of Waldo.', '2007-06-27 21:08:15.000000', NULL, 1),
(3843342, 542632, 45475, '<td valign="top">Hehe, funny photo op. Looks a bit hazy though. Maybe a contrast boost would help?</td>', 'Hehe, funny photo op. Looks a bit hazy though. Maybe a contrast boost would help?', '2007-06-27 21:08:59.000000', NULL, 1),
(3843343, 541794, 76430, '<td valign="top">Looking up partially hidden by the right branch.  Nice scene that would have been helped with more sunlight.</td>', 'Looking up partially hidden by the right branch.  Nice scene that would have been helped with more sunlight.', '2007-06-27 21:09:02.000000', NULL, 1),
(3843348, 538785, 45475, '<td valign="top">Weird, but interesting! Could have benefited from a bit of straightening though.</td>', 'Weird, but interesting! Could have benefited from a bit of straightening though.', '2007-06-27 21:10:47.000000', NULL, 1),
(3843350, 542477, 35274, '<td valign="top">Well, I must say, it''s a very interesting image. Especially with the long exposure effects, but it wasn''t hard in the least bit finding Waldo :\</td>', 'Well, I must say, it''s a very interesting image. Especially with the long exposure effects, but it wasn''t hard in the least bit finding Waldo :\', '2007-06-27 21:11:41.000000', NULL, 1),
(3843353, 541033, 76430, '<td valign="top">Standing on the street towards the right.  Interesting building and good composition.</td>', 'Standing on the street towards the right.  Interesting building and good composition.', '2007-06-27 21:12:11.000000', NULL, 1),
(3843355, 539518, 76430, '<td valign="top">It''s very obvious where Waldo is, but you did a very good job with matching the bands of color between the girl and graffiti.</td>', 'It''s very obvious where Waldo is, but you did a very good job with matching the bands of color between the girl and graffiti.', '2007-06-27 21:12:18.000000', NULL, 1),
(3843356, 542880, 45475, '<td valign="top">Exposure''s not quite right here and the treetops are suffering for it. Good try  though!</td>', 'Exposure''s not quite right here and the treetops are suffering for it. Good try  though!', '2007-06-27 21:12:29.000000', NULL, 1),
(3843360, 542775, 45475, '<td valign="top">Nice. The little Waldo blends in well with the surrounds.</td>', 'Nice. The little Waldo blends in well with the surrounds.', '2007-06-27 21:13:36.000000', NULL, 1),
(3843363, 542092, 45475, '<td valign="top">Ok, I''m stumped :D Interesting urban scene, well done.</td>', 'Ok, I''m stumped :D Interesting urban scene, well done.', '2007-06-27 21:14:45.000000', NULL, 1),
(3843370, 541916, 45475, '<td valign="top">Gone? Waldo''s GONE??? Oh well, cool shot anyways. Love how the shadows frame, nice work.</td>', 'Gone? Waldo''s GONE??? Oh well, cool shot anyways. Love how the shadows frame, nice work.', '2007-06-27 21:16:16.000000', NULL, 1),
(3843375, 542741, 45475, '<td valign="top">Holy cow, he has to climb that?! Determination indeed. Well shot.</td>', 'Holy cow, he has to climb that?! Determination indeed. Well shot.', '2007-06-27 21:17:08.000000', NULL, 1),
(3843378, 542853, 45475, '<td valign="top">Found him! Nice work, cool greens :)</td>', 'Found him! Nice work, cool greens :)', '2007-06-27 21:17:59.000000', NULL, 1),
(3843386, 542869, 45475, '<td valign="top">Sad. Probably could do with a more grittier contrast to push the message across. Nice work though.</td>', 'Sad. Probably could do with a more grittier contrast to push the message across. Nice work though.', '2007-06-27 21:19:58.000000', NULL, 1),
(3843388, 540746, 45475, '<td valign="top">Bucolic. And I like the way you spell gray :)</td>', 'Bucolic. And I like the way you spell gray :)', '2007-06-27 21:20:39.000000', NULL, 1),
(3843390, 542092, 76430, '<td valign="top">Somewhere in Europe based on the signs.  Leaning against the 2nd car on the left?</td>', 'Somewhere in Europe based on the signs.  Leaning against the 2nd car on the left?', '2007-06-27 21:22:40.000000', NULL, 1),
(3843391, 542626, 45475, '<td valign="top">Way overexposed unfortunately and very hazy in the distance. You could probably get away with a white sky if you convert to b&amp;w though. But you''re still going to need some Curves adjustment for the haze.</td>', 'Way overexposed unfortunately and very hazy in the distance. You could probably get away with a white sky if you convert to b&w though. But you''re still going to need some Curves adjustment for the haze.', '2007-06-27 21:22:54.000000', NULL, 1),
(3843393, 541986, 76430, '<td valign="top">At the bottom.  Beautiful scene!</td>', 'At the bottom.  Beautiful scene!', '2007-06-27 21:23:20.000000', NULL, 1),
(3843397, 542816, 76430, '<td valign="top">Sitting on the bank on the right against the first tree trunk.  Based on the hanging bikini I''m sorry "Waldo" is so far away.</td>', 'Sitting on the bank on the right against the first tree trunk.  Based on the hanging bikini I''m sorry "Waldo" is so far away.', '2007-06-27 21:24:52.000000', NULL, 1),
(3843398, 542452, 45475, '<td valign="top">BAM! In your face bright colour, yeah. Heh, took me a while to realise the scale here. Everything looked odd and plastic... then I spotted Waldo and the penny dropped. Excellent work!</td>', 'BAM! In your face bright colour, yeah. Heh, took me a while to realise the scale here. Everything looked odd and plastic... then I spotted Waldo and the penny dropped. Excellent work!', '2007-06-27 21:25:42.000000', NULL, 1),
(3843399, 542848, 76430, '<td valign="top">Either the head in the lower left, or if that''s a buoy the people standing on the boat.  I see several people in this shot.</td>', 'Either the head in the lower left, or if that''s a buoy the people standing on the boat.  I see several people in this shot.', '2007-06-27 21:25:43.000000', NULL, 1),
(3843401, 540553, 76430, '<td valign="top">left side of statue base, but it blends in fairly well.</td>', 'left side of statue base, but it blends in fairly well.', '2007-06-27 21:25:58.000000', NULL, 1),
(3843402, 542106, 76430, '<td valign="top">A head stickig out above the tarp on the white boat.  I took a minute to find it.  This is quite a complicated picture, but very suitable for a What''s Waldo challenge.</td>', 'A head stickig out above the tarp on the white boat.  I took a minute to find it.  This is quite a complicated picture, but very suitable for a What''s Waldo challenge.', '2007-06-27 21:26:08.000000', NULL, 1),
(3843403, 542608, 76430, '<td valign="top">Working on the left side of the left pipeline.  Nice geometry and forest.</td>', 'Working on the left side of the left pipeline.  Nice geometry and forest.', '2007-06-27 21:26:42.000000', NULL, 1),
(3843404, 542365, 76430, '<td valign="top">Standing on the bent tree trunk.  Beautiful scene.</td>', 'Standing on the bent tree trunk.  Beautiful scene.', '2007-06-27 21:27:01.000000', NULL, 1),
(3843405, 538679, 76430, '<td valign="top">I don''t see anything on land, but I see several shapes in the water.  Is one of them Waldo?</td>', 'I don''t see anything on land, but I see several shapes in the water.  Is one of them Waldo?', '2007-06-27 21:28:28.000000', NULL, 1),
(3843407, 540468, 76430, '<td valign="top">Very young soldier in camo.  Looks like he''s growing out of the ivy.  That''s not poison ivy is it?</td>', 'Very young soldier in camo.  Looks like he''s growing out of the ivy.  That''s not poison ivy is it?', '2007-06-27 21:29:19.000000', NULL, 1),
(3843409, 542855, 76430, '<td valign="top">Sleeping outside the storefront.</td>', 'Sleeping outside the storefront.', '2007-06-27 21:29:41.000000', NULL, 1),
(3843410, 542857, 62787, '<td valign="top">The shade hugs my heart.</td>', 'The shade hugs my heart.', '2007-06-27 21:29:52.000000', NULL, 1),
(3843411, 542309, 45475, '<td valign="top">Nice. Love the colour blocks in this. Great way to take advantage of the sun at your back. For me, this would have been even more awesome if the boat wasn''t there.</td>', 'Nice. Love the colour blocks in this. Great way to take advantage of the sun at your back. For me, this would have been even more awesome if the boat wasn''t there.', '2007-06-27 21:30:13.000000', NULL, 1),
(3843412, 542857, 76430, '<td valign="top">Standing at the bend in the path.  It was hard to pick out and blends in well with the road.</td>', 'Standing at the bend in the path.  It was hard to pick out and blends in well with the road.', '2007-06-27 21:30:31.000000', NULL, 1),
(3843414, 542852, 76430, '<td valign="top">In the field with something covering the head?</td>', 'In the field with something covering the head?', '2007-06-27 21:31:00.000000', NULL, 1),
(3843415, 541273, 55199, '<td valign="top">Good focus and composition, but the image doesn''t really hold my interest.</td>', 'Good focus and composition, but the image doesn''t really hold my interest.', '2007-06-27 21:31:10.000000', NULL, 1),
(3843416, 540915, 76430, '<td valign="top">Blurred in the time exposure right in front of the building.  Nice coloring.</td>', 'Blurred in the time exposure right in front of the building.  Nice coloring.', '2007-06-27 21:31:25.000000', NULL, 1),
(3843417, 540567, 76430, '<td valign="top">Riding a Jetski or something in the surf.  Nice vignette.</td>', 'Riding a Jetski or something in the surf.  Nice vignette.', '2007-06-27 21:31:59.000000', NULL, 1),
(3843418, 542232, 45475, '<td valign="top">Gotcha! Yeah, kiwis and aussies know him as Wally too. Trust the Americans to wanna do things their way ;)</td>', 'Gotcha! Yeah, kiwis and aussies know him as Wally too. Trust the Americans to wanna do things their way ;)', '2007-06-27 21:32:21.000000', NULL, 1),
