(3844321, 542812, 42013, '<td valign="top">Very nice textures, and a good job of placing ''waldo''</td>', 'Very nice textures, and a good job of placing ''waldo''', '2007-06-28 02:08:19.000000', NULL, 1),
(3844325, 542652, 42013, '<td valign="top">This is a nice version too, maybe a little heavy in the foreground but still good.</td>', 'This is a nice version too, maybe a little heavy in the foreground but still good.', '2007-06-28 02:08:47.000000', NULL, 1),
(3844326, 540468, 42013, '<td valign="top">Realtree? ;)</td>', 'Realtree? ;)', '2007-06-28 02:08:58.000000', NULL, 1),
(3844329, 540932, 66398, '<td valign="top">A little overprocessed on the sky (its grainy) You increased contrast and played with shadows and highlights right? It works but then you get the grainy look so maybe neat image would have helped or possibly gausian blur? I don''t have ni myself but plan to get it. The water looks good the way its processed though. Okay now Waldo is..... on top of the wave toward the left just to the left of the spray?</td>', 'A little overprocessed on the sky (its grainy) You increased contrast and played with shadows and highlights right? It works but then you get the grainy look so maybe neat image would have helped or possibly gausian blur? I don''t have ni myself but plan to get it. The water looks good the way its processed though. Okay now Waldo is..... on top of the wave toward the left just to the left of the spray?', '2007-06-28 02:10:14.000000', NULL, 1),
(3844335, 542858, 66398, '<td valign="top">The sky could use a little more contrast to bring out the clouds a bit. And the building looks a tad bit underexposed but might be compensated with midtone contrast. Interesting building with character. Waldo is in the doorway to the far left.</td>', 'The sky could use a little more contrast to bring out the clouds a bit. And the building looks a tad bit underexposed but might be compensated with midtone contrast. Interesting building with character. Waldo is in the doorway to the far left.', '2007-06-28 02:12:32.000000', NULL, 1),
(3844340, 542372, 42013, '<td valign="top">Wow, that is an interesting perspective. I guess its all blurred water. Really otherworldly.</td>', 'Wow, that is an interesting perspective. I guess its all blurred water. Really otherworldly.', '2007-06-28 02:15:12.000000', NULL, 1),
(3844342, 541982, 42013, '<td valign="top">I''m guessing lower right or upper left on the log?????</td>', 'I''m guessing lower right or upper left on the log?????', '2007-06-28 02:15:48.000000', NULL, 1),
(3844345, 540833, 66398, '<td valign="top">Oh how pretty. This is beautifully composed and the colors are so vibrant. A couple of extremely nitpicky things I think would make this better for me... (and these aren''t anything you could have done I know) is if those swans there were more toward the middle of that water and if the wheel was spinning with water going. Like I said those aren''t things that were under your control so I''m not docking you for it I just think it would''ve been cool.  Oh... Waldo is in the window btw. 10 and a fave...</td>', 'Oh how pretty. This is beautifully composed and the colors are so vibrant. A couple of extremely nitpicky things I think would make this better for me... (and these aren''t anything you could have done I know) is if those swans there were more toward the middle of that water and if the wheel was spinning with water going. Like I said those aren''t things that were under your control so I''m not docking you for it I just think it would''ve been cool.  Oh... Waldo is in the window btw. 10 and a fave...', '2007-06-28 02:17:20.000000', NULL, 1),
(3844358, 542459, 42013, '<td valign="top">This has structor written all over it. Dramatic sky, skillful post, lovely colors, etc. Nice work. I think I see waldo in the hut.???</td>', 'This has structor written all over it. Dramatic sky, skillful post, lovely colors, etc. Nice work. I think I see waldo in the hut.???', '2007-06-28 02:24:16.000000', NULL, 1),
(3844359, 542621, 66398, '<td valign="top">I like the colors here. There appears to be some blue saturation in the tree line above the road where you maybe saturated the whole shot then selectively masked or deleted the sky on that layer? If that''s what you did then you missed some of it in the tree line. If not then I''m not sure what it is. Okay Waldo..... Is he sitting off the right side of the road about where the first bright spot is?</td>', 'I like the colors here. There appears to be some blue saturation in the tree line above the road where you maybe saturated the whole shot then selectively masked or deleted the sky on that layer? If that''s what you did then you missed some of it in the tree line. If not then I''m not sure what it is. Okay Waldo..... Is he sitting off the right side of the road about where the first bright spot is?', '2007-06-28 02:24:30.000000', NULL, 1),
(3844360, 542860, 42013, '<td valign="top">I hoped someone would do this. Kudos for being brave and giving us a more traditional view of waldo.</td>', 'I hoped someone would do this. Kudos for being brave and giving us a more traditional view of waldo.', '2007-06-28 02:24:51.000000', NULL, 1),
(3844363, 542500, 42013, '<td valign="top">Very nice tones and BW conversion. Well done.</td>', 'Very nice tones and BW conversion. Well done.', '2007-06-28 02:25:21.000000', NULL, 1),
(3844364, 541405, 42013, '<td valign="top">Left side, on the path?? Beautiful picture with perfect exposure.</td>', 'Left side, on the path?? Beautiful picture with perfect exposure.', '2007-06-28 02:25:56.000000', NULL, 1),
(3844367, 542387, 42013, '<td valign="top">Dramatic structure. Waldo is tiny by comparison.</td>', 'Dramatic structure. Waldo is tiny by comparison.', '2007-06-28 02:26:18.000000', NULL, 1),
(3844368, 542862, 42013, '<td valign="top">How sweet, a tourist waldo ;)</td>', 'How sweet, a tourist waldo ;)', '2007-06-28 02:26:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3844371, 542608, 66398, '<td valign="top">He''s over on the left with an orange hat on.  Great exposure here. I''m beginning to really like leading lines alot. What are these things anyway?</td>', 'He''s over on the left with an orange hat on.  Great exposure here. I''m beginning to really like leading lines alot. What are these things anyway?', '2007-06-28 02:27:25.000000', NULL, 1),
(3844375, 542111, 66398, '<td valign="top">"She" is wearing a green dress at the top of the rocks. Nice composition and good exposure.</td>', '"She" is wearing a green dress at the top of the rocks. Nice composition and good exposure.', '2007-06-28 02:30:01.000000', NULL, 1),
(3844401, 542781, 66398, '<td valign="top">like the first morning. Blackbird has spoken like the first song.... sorry got carried away... Okay Waldo is on the shore on the right side. Did you use a polarizer? If not it may have helped so that you could get a little more exposure on the trees and still keep the nice exposure you have on the sky. I may not know what I''m talking about here because I''ve only just recently bought one and haven''t used it yet so take what I say with a grain of salt. I was just looking for the trees to be a little brighter.</td>', 'like the first morning. Blackbird has spoken like the first song.... sorry got carried away... Okay Waldo is on the shore on the right side. Did you use a polarizer? If not it may have helped so that you could get a little more exposure on the trees and still keep the nice exposure you have on the sky. I may not know what I''m talking about here because I''ve only just recently bought one and haven''t used it yet so take what I say with a grain of salt. I was just looking for the trees to be a little brighter.', '2007-06-28 02:39:47.000000', NULL, 1),
(3844405, 542634, 66398, '<td valign="top">It looks like you have a pretty good dof but just need a little better focus. Waldo''s face is left center.</td>', 'It looks like you have a pretty good dof but just need a little better focus. Waldo''s face is left center.', '2007-06-28 02:41:46.000000', NULL, 1),
(3844410, 542261, 66398, '<td valign="top">I love buildings with character like this one. Waldo is peeking out from between the house and the shed</td>', 'I love buildings with character like this one. Waldo is peeking out from between the house and the shed', '2007-06-28 02:44:10.000000', NULL, 1),
(3844417, 540929, 76430, '<td valign="top">Good one!  Painted face to the right of flowers.  Nice work.</td>', 'Good one!  Painted face to the right of flowers.  Nice work.', '2007-06-28 02:52:34.000000', NULL, 1),
