(3845218, 542078, 63269, '<td valign="top">Beautiful image!</td>', 'Beautiful image!', '2007-06-28 13:00:28.000000', NULL, 1),
(3845221, 542329, 63269, '<td valign="top">I love the tones, and shades of color in the sky, and the silvery sheen of the water. Beautiful!</td>', 'I love the tones, and shades of color in the sky, and the silvery sheen of the water. Beautiful!', '2007-06-28 13:00:57.000000', NULL, 1),
(3845223, 541723, 63269, '<td valign="top">I''m not really sure which is supposed to be the waldo... but neat idea!</td>', 'I''m not really sure which is supposed to be the waldo... but neat idea!', '2007-06-28 13:01:34.000000', NULL, 1),
(3845227, 539518, 63269, '<td valign="top">Completely awesome use of camoflauge and color. Just as a thought, it may have been interesting to have a different composition, instead of centering it... But it''s still a great photo! :)</td>', 'Completely awesome use of camoflauge and color. Just as a thought, it may have been interesting to have a different composition, instead of centering it... But it''s still a great photo! :)', '2007-06-28 13:02:27.000000', NULL, 1),
(3845229, 542492, 63269, '<td valign="top">I''m not really sure how this meets the challenge, and I''m not really sure I like the editing here either. But I can tell this is a nice clear image, and I like the sepia tones!</td>', 'I''m not really sure how this meets the challenge, and I''m not really sure I like the editing here either. But I can tell this is a nice clear image, and I like the sepia tones!', '2007-06-28 13:03:17.000000', NULL, 1),
(3845230, 542621, 63269, '<td valign="top">Beautiful rich colors, and lovely tones! I can''t find the waldo, so you must have hidden him <i>quite</i> well!</td>', 'Beautiful rich colors, and lovely tones! I can''t find the waldo, so you must have hidden him quite well!', '2007-06-28 13:04:04.000000', NULL, 1),
(3845231, 542625, 63269, '<td valign="top">The composition is a little cluttered. My eye wants to wander all over, instead of resting one one particular spot. But still, it''s a very pleasant image, and perfect use of black and white, the contrasts and lighting is beautiful! :)</td>', 'The composition is a little cluttered. My eye wants to wander all over, instead of resting one one particular spot. But still, it''s a very pleasant image, and perfect use of black and white, the contrasts and lighting is beautiful! :)', '2007-06-28 13:05:58.000000', NULL, 1),
(3845238, 542874, 28710, '<td valign="top">beautiful candidate for HDR.</td>', 'beautiful candidate for HDR.', '2007-06-28 13:09:33.000000', NULL, 1),
(3845245, 542854, 63269, '<td valign="top">I love your post-editing here, and the gold and purple colors are wonderful.  Great image!</td>', 'I love your post-editing here, and the gold and purple colors are wonderful.  Great image!', '2007-06-28 13:12:51.000000', NULL, 1),
(3845247, 542428, 63269, '<td valign="top">Superb! Excellent! I love where you hid him; it gives the image a sort of bizarre atmosphere when you see the head sticking up from the sand. Nice tones and colors too. Good shot.</td>', 'Superb! Excellent! I love where you hid him; it gives the image a sort of bizarre atmosphere when you see the head sticking up from the sand. Nice tones and colors too. Good shot.', '2007-06-28 13:14:07.000000', NULL, 1),
(3845252, 541994, 63269, '<td valign="top">The bear is nicely hidden, but the image itself isn''t... well... It''s a little washed out. Maybe some more contrast would help with that. And some of the details are sort of smeared and blurry. But excellent try! This might be cool in black and white. Hope the bear went after those berries and didn''t get curious about you!:)</td>', 'The bear is nicely hidden, but the image itself isn''t... well... It''s a little washed out. Maybe some more contrast would help with that. And some of the details are sort of smeared and blurry. But excellent try! This might be cool in black and white. Hope the bear went after those berries and didn''t get curious about you!:)', '2007-06-28 13:16:19.000000', NULL, 1),
(3845253, 542818, 63269, '<td valign="top">I love the moody contrasts and colors - neat processing!</td>', 'I love the moody contrasts and colors - neat processing!', '2007-06-28 13:16:39.000000', NULL, 1),
