(3851187, 542741, 38464, '<td valign="top">Wow! Beautiful setting. My heart skipped a minute at the sheer massiveness and realization of how far ''Waldo'' still had to go.</td>', 'Wow! Beautiful setting. My heart skipped a minute at the sheer massiveness and realization of how far ''Waldo'' still had to go.', '2007-06-30 13:19:24.000000', NULL, 1),
(3851190, 542871, 60495, '<td valign="top">Very cool, great phot and hard to find waldo even though he is right there looking at you. 10</td>', 'Very cool, great phot and hard to find waldo even though he is right there looking at you. 10', '2007-06-30 13:21:25.000000', NULL, 1),
