(3851203, 542071, 38464, '<td valign="top">*laughs* Nicely blended in! :)</td>', '*laughs* Nicely blended in! :)', '2007-06-30 13:29:20.000000', NULL, 1),
(3851207, 542492, 60495, '<td valign="top">Unless I miss my quess this looks like an attept for the brown, Good luck, personally I really like this one, the browns have been overdone, the lighting is not fantastic and the overblown areas show up nicely. The one thing missing is waldo unless the horses name is waldo in which case I am sorry I did not know and may have scored it higher if I would have known.</td>', 'Unless I miss my quess this looks like an attept for the brown, Good luck, personally I really like this one, the browns have been overdone, the lighting is not fantastic and the overblown areas show up nicely. The one thing missing is waldo unless the horses name is waldo in which case I am sorry I did not know and may have scored it higher if I would have known.', '2007-06-30 13:31:28.000000', NULL, 1),
(3851220, 541405, 38464, '<td valign="top">Took me a minute, but finally saw it. Beautiful setting! :)</td>', 'Took me a minute, but finally saw it. Beautiful setting! :)', '2007-06-30 13:37:53.000000', NULL, 1),
(3851255, 540514, 38464, '<td valign="top">At first I thought it was an elevator shaft - I like the angle. :)</td>', 'At first I thought it was an elevator shaft - I like the angle. :)', '2007-06-30 14:07:48.000000', NULL, 1),
(3851256, 542602, 38464, '<td valign="top">Yes! Someone else who has a small kitchen too! :D  Okay, that eye peeking out is just eerie. :)</td>', 'Yes! Someone else who has a small kitchen too! :D  Okay, that eye peeking out is just eerie. :)', '2007-06-30 14:09:36.000000', NULL, 1),
(3851264, 542652, 38464, '<td valign="top">I like the different shapes and patterns. :) I''d have different title though. And no, I didn''t mark down for my personal quip.</td>', 'I like the different shapes and patterns. :) I''d have different title though. And no, I didn''t mark down for my personal quip.', '2007-06-30 14:16:06.000000', NULL, 1),
(3851270, 542232, 38464, '<td valign="top">Nicely hidden! :)</td>', 'Nicely hidden! :)', '2007-06-30 14:18:38.000000', NULL, 1),
