(3851278, 542875, 38464, '<td valign="top">Beautiful setting, love the tonal color and nice hiding of ''Waldo''. :)</td>', 'Beautiful setting, love the tonal color and nice hiding of ''Waldo''. :)', '2007-06-30 14:22:48.000000', NULL, 1),
