(3851592, 541784, 6519, '<td valign="top">Wow, that was hard to find!</td>', 'Wow, that was hard to find!', '2007-06-30 17:28:00.000000', NULL, 1),
(3851665, 541784, 65234, '<td valign="top">I came back to this 3x before I finally found Waldo!  Much tougher with no color clues, I must say.  Fascinating graveyard; it looks ancient.</td>', 'I came back to this 3x before I finally found Waldo!  Much tougher with no color clues, I must say.  Fascinating graveyard; it looks ancient.', '2007-06-30 18:15:37.000000', NULL, 1),
(3851667, 541744, 65234, '<td valign="top">Aww, cute escapee.</td>', 'Aww, cute escapee.', '2007-06-30 18:16:08.000000', NULL, 1),
(3851670, 542372, 73121, '<td valign="top">Beautiful capture.  The perspective and maybe the shutter speed are messing with my eyes.  It almost seems as if the man is looking into a pool of water.  lol maybe it is?  Great colors just kept me looking.</td>', 'Beautiful capture.  The perspective and maybe the shutter speed are messing with my eyes.  It almost seems as if the man is looking into a pool of water.  lol maybe it is?  Great colors just kept me looking.', '2007-06-30 18:16:37.000000', NULL, 1),
(3851673, 542743, 73121, '<td valign="top">I really like the processing on this, good greans and greys.  Good job on the focus, I think it works good for this shot.</td>', 'I really like the processing on this, good greans and greys.  Good job on the focus, I think it works good for this shot.', '2007-06-30 18:18:44.000000', NULL, 1),
(3851675, 541736, 65234, '<td valign="top">Hmm.  Not 100% sure, but am guessing Waldo is blocking that last light on the middle level on the left.  Something is, anyway.  Nice star effect on the lights.</td>', 'Hmm.  Not 100% sure, but am guessing Waldo is blocking that last light on the middle level on the left.  Something is, anyway.  Nice star effect on the lights.', '2007-06-30 18:19:12.000000', NULL, 1),
(3851680, 542853, 65234, '<td valign="top">This feels tilted but there isn''t anough perspective to tell if you were on a hill or had your camera tilted.  Found Waldo, though.</td>', 'This feels tilted but there isn''t anough perspective to tell if you were on a hill or had your camera tilted.  Found Waldo, though.', '2007-06-30 18:20:45.000000', NULL, 1),
(3851681, 541023, 73121, '<td valign="top">Took me longer than I expected to find waldo.  Great perspective and exposure on this image.  Looks like a really beautiful place.</td>', 'Took me longer than I expected to find waldo.  Great perspective and exposure on this image.  Looks like a really beautiful place.', '2007-06-30 18:20:46.000000', NULL, 1),
(3851685, 542420, 65234, '<td valign="top">Cute scene!</td>', 'Cute scene!', '2007-06-30 18:21:48.000000', NULL, 1),
(3851687, 542743, 65234, '<td valign="top">Spooky processing.  Is Waldo seeking out the Blair Witch?</td>', 'Spooky processing.  Is Waldo seeking out the Blair Witch?', '2007-06-30 18:22:47.000000', NULL, 1),
(3851688, 541489, 73121, '<td valign="top">Nice interesting image here, really makes me wonder why those two people are there.</td>', 'Nice interesting image here, really makes me wonder why those two people are there.', '2007-06-30 18:22:49.000000', NULL, 1),
(3851690, 542372, 65234, '<td valign="top">Wow.  Gorgeous image!  Wondr what Waldo ws contemplating?</td>', 'Wow.  Gorgeous image!  Wondr what Waldo ws contemplating?', '2007-06-30 18:24:35.000000', NULL, 1),
