(3854873, 542594, 55199, '<td valign="top">I like how you caught the way the branches form an arch roofed path.</td>', 'I like how you caught the way the branches form an arch roofed path.', '2007-07-01 20:52:01.000000', NULL, 1),
(3854905, 541994, 55199, '<td valign="top">Is Waldo wearing green and half hidden behind the white birch (3rd trunk from the right)? While I like a good challenge, it may have been better to make Waldo a little more obvious for this photo.</td>', 'Is Waldo wearing green and half hidden behind the white birch (3rd trunk from the right)? While I like a good challenge, it may have been better to make Waldo a little more obvious for this photo.', '2007-07-01 21:00:41.000000', NULL, 1),
