INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3855224, 541722, 55199, '<td valign="top">nice contrast of color and exposure. I think I''d like it better though if you cropped the top so the moon and star weren''t there.  It would make the photo feel more balanced and I wouldn''t be distracted by them.</td>', 'nice contrast of color and exposure. I think I''d like it better though if you cropped the top so the moon and star weren''t there.  It would make the photo feel more balanced and I wouldn''t be distracted by them.', '2007-07-01 22:34:34.000000', NULL, 1),
