(5461160, 542106, 103992, '<td valign="top">really well hidden. i had to look at the photo for a few minutes in a few different days. well done.</td>', 'really well hidden. i had to look at the photo for a few minutes in a few different days. well done.', '2009-05-01 12:39:08.000000', NULL, 0),
(5490267, 540929, 99263, '<td valign="top">I loved your idea so much I decided to copy it with my wife posing as model. I painted the zebra stripe background on a large sheet of hardboard and that was more difficult then I had thought it would be. I found a pattern to copy from on the internet. Then I painted my wife''s face. I could not get nice big sunflowers at the florist (only small one''s as the season for them has not yet started) so I went to the garden center and found 3 nice big fake one''s.<br/>All in all it was a fun project. I hope you like it. I hope you don''t mind that I copied your idea. :)<br/><a href="//g.imagehost.org/0348/Zonnebloemen.jpg" rel="nofollow" target="_blank">//g.imagehost.org/0348/Zonnebloemen.jpg</a><br/><br/><i>Message edited by author 2009-05-25 02:11:48.</i></td>', 'I loved your idea so much I decided to copy it with my wife posing as model. I painted the zebra stripe background on a large sheet of hardboard and that was more difficult then I had thought it would be. I found a pattern to copy from on the internet. Then I painted my wife''s face. I could not get nice big sunflowers at the florist (only small one''s as the season for them has not yet started) so I went to the garden center and found 3 nice big fake one''s.All in all it was a fun project. I hope you like it. I hope you don''t mind that I copied your idea. :)//g.imagehost.org/0348/Zonnebloemen.jpg', '2009-05-17 17:11:10.000000', '2009-05-25 03:11:48.000000', 0),
(5504437, 540929, 99263, '<td valign="top">Gaby I must thank you for your inspiration. I entered my photo of Sunflowers in a large regional newspaper photo contest here where I live and I won 1st place with it. That was out of a total of 879 entries. :)</td>', 'Gaby I must thank you for your inspiration. I entered my photo of Sunflowers in a large regional newspaper photo contest here where I live and I won 1st place with it. That was out of a total of 879 entries. :)', '2009-05-29 08:03:24.000000', NULL, 0),
